Agente con acceso a archivos.ejemplo:
from pathlib import Path
BASE = Path("/workspace/project").resolve()
def safe_read(rel_path: str) -> str:
    target = (BASE / rel_path).resolve()
    if not target.is_relative_to(BASE) or target.name == ".env":
        raise PermissionError("Ruta fuera de alcance permitido")
    return target.read_text(encoding="utf-8")

